import{_ as a,c as r,o as e,V as t,cI as o}from"./chunks/framework.tJhZUYt7.js";const S=JSON.parse('{"title":"一、简介","description":"","frontmatter":{},"headers":[],"relativePath":"rear/java/Java开发框架/Spring/简介.md","filePath":"rear/java/Java开发框架/Spring/简介.md","lastUpdated":1719821588000}'),i={name:"rear/java/Java开发框架/Spring/简介.md"},n=t('<h1 id="一、简介" tabindex="-1">一、简介 <a class="header-anchor" href="#一、简介" aria-label="Permalink to &quot;一、简介&quot;">​</a></h1><h2 id="一、spring是什么" tabindex="-1">一、Spring是什么 <a class="header-anchor" href="#一、spring是什么" aria-label="Permalink to &quot;一、Spring是什么&quot;">​</a></h2><blockquote><p>Spring是分层的Java SE/EE应用full-stack轻量级开源框架，以<code>loC</code> ( lnverse Of Control :反转控制)和<code>AOP</code> ( Aspect Oriented Programming :面向切面编程)为内核。</p><br><p>提供了<b style="color:red;">展现层SpringMVC</b>和<b style="color:red;">持久层Spring JDBCTemplate</b>以及<b style="color:red;">业务层事务管理</b>等众多的企业级应用技术，还能整合开源世界众多著名的第三方框架和类库，逐渐成为使用最多的JavaEE企业应用开源框架。</p></blockquote><h2 id="二、spring的优势" tabindex="-1">二、Spring的优势 <a class="header-anchor" href="#二、spring的优势" aria-label="Permalink to &quot;二、Spring的优势&quot;">​</a></h2><p><b style="color:red;">（1）方便解耦，简化开发</b> 通过Spring提供的loC容器，可以将对象间的依赖关系交由Spring进行控制，避免硬编码所造成的过度耦合。用户也不必再为单例模式类、属性文件解析等这些很底层的需求编写代码，可以更专注于上层的应用。</p><p><b style="color:red;">（2）AOP编程的支持</b> 通过Spring的AOP功能，方便进行面向切面编程，许多不容易用传统OOP实现的功能可以通过AOP轻松实现。</p><p><b style="color:red;">（3）声明式事务的支持</b> 可以将我们从单调烦闷的事务管理代码中解脱出来，通过声明式方式灵活的进行事务管理，提高开发效率和质量。</p><p><b style="color:red;">（4）方便程序的测试</b> 可以用非容器依赖的编程方式进行几乎所有的测试工作，测试不再是昂贵的操作，而是随手可做的事情。</p><p><b style="color:red;">（5）方便集成各种优秀框架</b> Spring对各种优秀框架(Struts、Hibernate、Hessian、Quartz等)的支持。</p><p><b style="color:red;">（6）降低JavaEE API的使用难度</b> Spring对JavaEEAPI (如JDBC、JavaMail、远程调用等）进行了薄薄的封装层，使这些API的使用难度大为降低。</p><h2 id="三、spring的体系" tabindex="-1">三、Spring的体系 <a class="header-anchor" href="#三、spring的体系" aria-label="Permalink to &quot;三、Spring的体系&quot;">​</a></h2><img src="'+o+'">',12),l=[n];function p(s,c,d,_,b,g){return e(),r("div",null,l)}const m=a(i,[["render",p]]);export{S as __pageData,m as default};
